1	import type { Metadata } from "next";
2	import { v2AdminClient } from "@/lib/v2/supabase";
3	import { getPlatformContext } from "@/lib/v2/context";
4	import PwaRegistrar from "./PwaRegistrar";
5	import MusicProvider from "./(event)/MusicProvider";
6	import { NameModeProvider } from "./(event)/NameMode";
7	import SimBanner from "./(event)/SimBanner";
8	import { SimTimeProvider } from "./(event)/SimTime";
9	import { getSimAt, v2Now } from "@/lib/v2/simulator";
10	
11	/**
12	 * Org subtree wrapper. Purely additive: it points the PWA manifest + Apple title
13	 * at THIS org (overriding the root /manifest.json for /new/<slug> only) and
14	 * registers the service worker, so each tenant installs as its own app. Renders
15	 * children unchanged — the (event) shell and admin layouts nest inside it.
16	 */
17	export async function generateMetadata({
18	  params,
19	}: {
20	  params: Promise<{ slug: string }>;
21	}): Promise<Metadata> {
22	  const { slug } = await params;
23	  const admin = v2AdminClient();
24	  const { data: org } = await admin
25	    .from("v2_organizations")
26	    .select("name, logo_url")
27	    .eq("slug", slug)
28	    .maybeSingle();
29	  const name = org?.name || "Golfapalooza";
30	  const base = `/new/${slug}`;
31	  // Cache-bust the favicon/app icon by the logo's unique filename, so changing
32	  // the logo swaps the browser tab + home-screen icon immediately (browsers cache
33	  // favicons hard; a stable URL would stay stale).
34	  const ver = org?.logo_url ? encodeURIComponent(org.logo_url.split("/").pop() || "1") : null;
35	  const meta: Metadata = {
36	    title: name,
37	    applicationName: name,
38	    manifest: `${base}/manifest.webmanifest`,
39	    appleWebApp: { capable: true, statusBarStyle: "default", title: name },
40	  };
41	  // Point the favicon + Apple touch icon at the org's logo (composited by the
42	  // icon route). Falls back to the app default when the org has no logo.
43	  if (ver) {
44	    meta.icons = {
45	      icon: [{ url: `${base}/icon?size=192&v=${ver}`, sizes: "192x192", type: "image/png" }],
46	      shortcut: [{ url: `${base}/icon?size=192&v=${ver}` }],
47	      apple: [{ url: `${base}/icon?size=512&v=${ver}`, sizes: "512x512", type: "image/png" }],
48	    };
49	  }
50	  return meta;
51	}
52	
53	export default async function OrgLayout({
54	  children,
55	  params,
56	}: {
57	  children: React.ReactNode;
58	  params: Promise<{ slug: string }>;
59	}) {
60	  const { slug } = await params;
61	  // Mount the music provider + name-mode at the ORG level (not the event group)
62	  // so a single audio session survives navigation to any /new/<slug>/* page —
63	  // the full-screen scorer, admin, etc. — instead of stopping when the (event)
64	  // layout unmounts. The mini-player renders here too, above the bottom nav.
65	  // Non-members get plain children; the inner layouts handle the redirect.
66	  const ctx = await getPlatformContext();
67	  const org = ctx?.orgs.find((o) => o.slug === slug);
68	  const simAt = await getSimAt();
69	  const serverNowMs = (await v2Now()).getTime();
70	
71	  if (!org) {
72	    return (
73	      <>
74	        <PwaRegistrar />
75	        {children}
76	      </>
77	    );
78	  }
79	
80	  return (
81	    <>
82	      <PwaRegistrar />
83	      {(ctx?.simulating || simAt) && <SimBanner name={ctx?.simulating ? ctx.simName : null} at={simAt} />}
84	      <SimTimeProvider serverNowMs={serverNowMs}>
85	        <NameModeProvider mode={org.name_display}>
86	          <MusicProvider orgId={org.id}>{children}</MusicProvider>
87	        </NameModeProvider>
88	      </SimTimeProvider>
89	    </>
90	  );
91	}
