1	import { redirect } from "next/navigation";
2	import { getPlatformContext } from "@/lib/v2/context";
3	import { v2ServerClient } from "@/lib/v2/supabase";
4	import EventShell from "./EventShell";
5	import { buildEventNav, isFeatureVisible, resolveFeatures, type FeatureRow } from "@/lib/v2/features";
6	import { v2Now } from "@/lib/v2/simulator";
7	
8	/**
9	 * Wraps the member-facing event experience in the fixed top-bar/bottom-nav shell.
10	 * Scoped to the (event) route group so /new/[slug]/admin/* does NOT get the shell.
11	 */
12	export default async function EventLayout({
13	  children,
14	  params,
15	}: {
16	  children: React.ReactNode;
17	  params: Promise<{ slug: string }>;
18	}) {
19	  const { slug } = await params;
20	  const ctx = await getPlatformContext();
21	  // Carry the group so the login screen brands to the group they were headed to.
22	  if (!ctx) redirect(`/new/signup?org=${encodeURIComponent(slug)}`);
23	  const org = ctx.orgs.find((o) => o.slug === slug);
24	  if (!org) redirect("/new");
25	  const isAdmin = org.role === "owner" || org.role === "admin";
26	
27	  const supabase = await v2ServerClient();
28	  const [meRes, unreadRes, chatMineRes, activeEventRes] = await Promise.all([
29	    supabase.from("v2_profiles").select("avatar_url").eq("id", ctx.userId).maybeSingle(),
30	    supabase
31	      .from("v2_notifications")
32	      .select("id", { count: "exact", head: true })
33	      .eq("user_id", ctx.userId)
34	      .eq("org_id", org.id)
35	      .eq("read", false)
36	      .not("type", "in", "(chat_message,chat_mention)"),
37	    supabase.from("v2_chat_room_members").select("room_id, hidden_at").eq("user_id", ctx.userId),
38	    supabase
39	      .from("v2_events")
40	      .select("id")
41	      .eq("org_id", org.id)
42	      .eq("status", "active")
43	      .order("start_date", { ascending: false })
44	      .limit(1)
45	      .maybeSingle(),
46	  ]);
47	
48	  // Resolve the feature registry into the shell nav (bottom-bar pins + "Everything"
49	  // launcher) and Music visibility. Group-wide features (Articles, Music…) apply
50	  // even with no active event; event overrides layer on when one exists. Degrades
51	  // to empty nav / Music-on if the registry table isn't present yet (data null).
52	  let pinned: ReturnType<typeof buildEventNav>["pinned"] = [];
53	  let launcher: ReturnType<typeof buildEventNav>["launcher"] = [];
54	  let musicEnabled = true;
55	  let chatEnabled = true;
56	  let photosEnabled = true;
57	  const activeEventId = (activeEventRes.data?.id as string | undefined) ?? null;
58	  const featFilter = activeEventId
59	    ? `event_id.is.null,event_id.eq.${activeEventId}`
60	    : "event_id.is.null";
61	  const { data: featRows } = await supabase
62	    .from("v2_event_features")
63	    .select(
64	      "feature_key, event_id, visibility, pinned, nav_order, label_override, public, availability, available_from, available_until",
65	    )
66	    .eq("org_id", org.id)
67	    .or(featFilter);
68	  const resolved = resolveFeatures((featRows as FeatureRow[] | null) ?? [], activeEventId ?? "");
69	  ({ pinned, launcher } = buildEventNav(slug, resolved, isAdmin, await v2Now()));
70	
71	  // The members directory ("loozers") is labelled per-org: use the group's
72	  // configured member noun (e.g. "Loozers") instead of the catalog default.
73	  const memberPlural = org.member_noun_plural || "Members";
74	  const relabelMembers = <T extends { key: string; label: string; blurb: string }>(f: T): T =>
75	    f.key === "loozers"
76	      ? { ...f, label: memberPlural, blurb: `The ${(org.member_noun || "member").toLowerCase()} directory.` }
77	      : f;
78	  pinned = pinned.map(relabelMembers);
79	  launcher = launcher.map((g) => ({ ...g, features: g.features.map(relabelMembers) }));
80	
81	  musicEnabled = isFeatureVisible(resolved, "music", isAdmin);
82	  chatEnabled = isFeatureVisible(resolved, "chat", isAdmin);
83	  photosEnabled = isFeatureVisible(resolved, "photos", isAdmin);
84	
85	  // Initial chat unread across my rooms (bounded recent window, like the badge API).
86	  let initialChatUnread = 0;
87	  const chatRoomIds = (chatMineRes.data || []).filter((m) => !m.hidden_at).map((m) => m.room_id);
88	  if (chatRoomIds.length) {
89	    const [receipts, recent, hiddenR] = await Promise.all([
90	      supabase.from("v2_chat_read_receipts").select("room_id, last_read_at").eq("user_id", ctx.userId).in("room_id", chatRoomIds),
91	      supabase
92	        .from("v2_chat_messages")
93	        .select("id, room_id, sender_id, created_at")
94	        .in("room_id", chatRoomIds)
95	        .order("created_at", { ascending: false })
96	        .limit(600),
97	      supabase.from("v2_chat_hidden_messages").select("message_id").eq("user_id", ctx.userId),
98	    ]);
99	    const lastRead = new Map((receipts.data || []).map((r) => [r.room_id, r.last_read_at]));
100	    const hiddenChat = new Set((hiddenR.data || []).map((h) => h.message_id));
101	    for (const msg of recent.data || []) {
102	      if (hiddenChat.has(msg.id)) continue;
103	      const lr = lastRead.get(msg.room_id);
104	      if (msg.sender_id !== ctx.userId && (!lr || msg.created_at > lr)) initialChatUnread += 1;
105	    }
106	  }
107	
108	  // NameMode + Music providers now live in the parent [slug] layout so audio
109	  // persists across the whole org (incl. the full-screen scorer). This layout
110	  // just mounts the event shell.
111	  return (
112	    <EventShell
113	      slug={slug}
114	      orgId={org.id}
115	      userId={ctx.userId}
116	      isAdmin={isAdmin}
117	      orgName={org.name}
118	      logoUrl={org.logo_url}
119	      userAvatarUrl={meRes.data?.avatar_url ?? null}
120	      initialUnreadCount={unreadRes.count ?? 0}
121	      initialChatUnread={initialChatUnread}
122	      pinned={pinned}
123	      launcher={launcher}
124	      musicEnabled={musicEnabled}
125	      chatEnabled={chatEnabled}
126	      photosEnabled={photosEnabled}
127	    >
128	      {children}
129	    </EventShell>
130	  );
131	}
