1	"use client";
2	
3	import { useCallback, useEffect, useState } from "react";
4	import Link from "next/link";
5	import { v2RealtimeClient } from "@/lib/v2/supabase-browser";
6	import type { RealtimeChannel } from "@supabase/supabase-js";
7	import { syncBadge } from "@/lib/v2/badge";
8	import { pushPermission, subscribeToV2Push } from "@/lib/v2/push-client";
9	import ProfileDrawer from "./ProfileDrawer";
10	import NotificationDrawer from "./NotificationDrawer";
11	import ChatDrawer from "./ChatDrawer";
12	import PhotosDrawer from "./PhotosDrawer";
13	import RoundsDrawer from "./RoundsDrawer";
14	import { useV2Music } from "./MusicProvider";
15	import FeatureIcon from "@/app/new/_components/FeatureIcon";
16	import type { NavFeature, LauncherGroup } from "@/lib/v2/features";
17	import styles from "./event-shell.module.css";
18	/* eslint-disable @next/next/no-img-element */
19	
20	const CHAT_TYPES = ["chat_message", "chat_mention"];
21	
22	// Music is NOT a shared-drawer key — it owns its own persistent overlay
23	// (mini-player + expandable) via MusicProvider so audio survives close/nav.
24	type DrawerKey = "chat" | "photos" | "rounds" | "profile" | "notifications";
25	
26	const DRAWERS: Record<DrawerKey, { title: string; body: string }> = {
27	  chat: { title: "Chat", body: "Group chat will live here." },
28	  photos: { title: "Photos", body: "The photo gallery will live here." },
29	  rounds: { title: "My Rounds", body: "Round tracking & scoring will live here." },
30	  profile: { title: "Profile", body: "" },
31	  notifications: { title: "Notifications", body: "Your notifications will live here." },
32	};
33	
34	/**
35	 * The event runtime shell (member app). Fixed top bar (function drawers) + fixed,
36	 * admin-configurable bottom nav. Per the hard rule, the bars sit ABOVE everything
37	 * (drawers slide over content but never over the bars) and never move.
38	 */
39	export default function EventShell({
40	  slug,
41	  orgId,
42	  userId,
43	  isAdmin,
44	  orgName,
45	  logoUrl,
46	  userAvatarUrl,
47	  initialUnreadCount,
48	  initialChatUnread,
49	  pinned,
50	  launcher,
51	  musicEnabled,
52	  chatEnabled,
53	  photosEnabled,
54	  children,
55	}: {
56	  slug: string;
57	  orgId: string;
58	  userId: string;
59	  isAdmin: boolean;
60	  orgName: string;
61	  logoUrl: string | null;
62	  userAvatarUrl: string | null;
63	  initialUnreadCount: number;
64	  initialChatUnread: number;
65	  pinned: NavFeature[];
66	  launcher: LauncherGroup[];
67	  musicEnabled: boolean;
68	  chatEnabled: boolean;
69	  photosEnabled: boolean;
70	  children: React.ReactNode;
71	}) {
72	  const [open, setOpen] = useState<DrawerKey | null>(null);
73	  const [everythingOpen, setEverythingOpen] = useState(false);
74	  // The My Rounds "log a round" form: header +/× toggles it. Reset in `toggle`
75	  // (any drawer switch) so reopening My Rounds always lands on the list.
76	  const [roundsFormOpen, setRoundsFormOpen] = useState(false);
77	  const [unread, setUnread] = useState(initialUnreadCount);
78	  const [chatUnread, setChatUnread] = useState(initialChatUnread);
79	  // A notification/activity deep-link target for a drawer (room or photo id),
80	  // consumed by ChatDrawer/PhotosDrawer on open, cleared when the drawer closes.
81	  const [deepLink, setDeepLink] = useState<{ room?: string; photo?: string; msg?: string; bulk?: string }>({});
82	  const music = useV2Music();
83	
84	  // Publish the bottom-nav footprint globally while the shell is mounted, so the
85	  // (org-level) mini-player can sit directly above the nav and content/drawers
86	  // can reserve the combined chrome height. Cleared on unmount (e.g. the
87	  // full-screen scorer, which has no bottom nav → --nav-h falls back to 0).
88	  useEffect(() => {
89	    const root = document.documentElement;
90	    root.style.setProperty("--nav-h", "calc(60px + env(safe-area-inset-bottom, 0px))");
91	    return () => {
92	      root.style.removeProperty("--nav-h");
93	    };
94	  }, []);
95	
96	  const refetchChatUnread = useCallback(async () => {
97	    try {
98	      const res = await fetch(`/api/v2/chat/unread?orgId=${orgId}`);
99	      if (res.ok) setChatUnread((await res.json()).unread ?? 0);
100	    } catch {
101	      /* ignore */
102	    }
103	  }, [orgId]);
104	
105	  const toggle = (k: DrawerKey) => {
106	    // Opening notifications marks everything read (the drawer does the write).
107	    if (k === "notifications") setUnread(0);
108	    // Manual open is never a deep-link — drop any stale room/photo target so a
109	    // reopened drawer doesn't jump back to a previously deep-linked item.
110	    setDeepLink((d) => (d.room || d.photo || d.msg || d.bulk ? {} : d));
111	    setEverythingOpen(false);
112	    setRoundsFormOpen(false);
113	    const willOpen = open !== k;
114	    // Closing chat: read receipts may have changed — refresh the badge.
115	    if (open === "chat" && k === "chat") refetchChatUnread();
116	    // Announce so the music overlay steps aside — one full-screen surface at a time.
117	    if (willOpen && typeof window !== "undefined") {
118	      window.dispatchEvent(new CustomEvent("ui:drawer-open", { detail: { name: k } }));
119	    }
120	    setOpen(willOpen ? k : null);
121	  };
122	
123	  // Open/close the "Everything" launcher (bottom sheet), coordinating with the
124	  // drawers and the music overlay so only one full-screen surface shows at once.
125	  const openEverything = () => {
126	    setDeepLink((d) => (d.room || d.photo || d.msg || d.bulk ? {} : d));
127	    const willOpen = !everythingOpen;
128	    if (willOpen && typeof window !== "undefined") {
129	      window.dispatchEvent(new CustomEvent("ui:drawer-open", { detail: { name: "everything" } }));
130	    }
131	    setEverythingOpen(willOpen);
132	  };
133	
134	  // Coordinate surfaces: opening the launcher closes any drawer; opening a drawer
135	  // (or expanding music) closes the launcher. Music also owns the shared drawers.
136	  useEffect(() => {
137	    const handler = (e: Event) => {
138	      const name = (e as CustomEvent<{ name?: string }>).detail?.name;
139	      if (!name) return;
140	      if (name === "everything") {
141	        setOpen(null);
142	      } else {
143	        setEverythingOpen(false);
144	        if (name === "music") setOpen(null);
145	      }
146	    };
147	    window.addEventListener("ui:drawer-open", handler);
148	    return () => window.removeEventListener("ui:drawer-open", handler);
149	  }, []);
150	
151	  // Deep-link on arrival: a tapped notification/activity lands on the home route
152	  // with ?open=<drawer>&room=/photo=. Open that drawer to the target, then strip
153	  // the params so a refresh/back doesn't re-fire. Read from window.location (not
154	  // useSearchParams) to avoid a Suspense boundary requirement.
155	  useEffect(() => {
156	    if (typeof window === "undefined") return;
157	    const p = new URLSearchParams(window.location.search);
158	    const target = p.get("open");
159	    if (!target) return;
160	    const room = p.get("room") ?? undefined;
161	    const photo = p.get("photo") ?? undefined;
162	    const msg = p.get("msg") ?? undefined;
163	    window.history.replaceState(null, "", window.location.pathname);
164	    // Defer state changes out of the effect body (avoids cascading-render lint).
165	    const raf = requestAnimationFrame(() => {
166	      if (target === "music") {
167	        if (musicEnabled) music.expandDrawer();
168	      } else if (target === "chat" && !chatEnabled) {
169	        /* chat is off for this viewer */
170	      } else if (target === "photos" && !photosEnabled) {
171	        /* photos is off for this viewer */
172	      } else if (target in DRAWERS) {
173	        setDeepLink({ room, photo, msg });
174	        window.dispatchEvent(new CustomEvent("ui:drawer-open", { detail: { name: target } }));
175	        setOpen(target as DrawerKey);
176	      }
177	    });
178	    return () => cancelAnimationFrame(raf);
179	  }, [music, musicEnabled, chatEnabled, photosEnabled]);
180	
181	  // Open a drawer on request from elsewhere (an Activity-feed row or an in-app
182	  // notification tap). detail may carry a deep target (room/photo).
183	  useEffect(() => {
184	    const handler = (e: Event) => {
185	      const detail = (e as CustomEvent<{ name?: string; room?: string; photo?: string; msg?: string; bulk?: string }>).detail;
186	      const name = detail?.name;
187	      if (name === "music") {
188	        if (musicEnabled) music.expandDrawer();
189	      } else if (name === "chat" && !chatEnabled) {
190	        /* off */
191	      } else if (name === "photos" && !photosEnabled) {
192	        /* off */
193	      } else if (name && name in DRAWERS) {
194	        if (detail?.room || detail?.photo || detail?.msg || detail?.bulk)
195	          setDeepLink({ room: detail.room, photo: detail.photo, msg: detail.msg, bulk: detail.bulk });
196	        window.dispatchEvent(new CustomEvent("ui:drawer-open", { detail: { name } }));
197	        setOpen(name as DrawerKey);
198	      }
199	    };
200	    window.addEventListener("ui:open-drawer", handler);
201	    return () => window.removeEventListener("ui:open-drawer", handler);
202	  }, [music, musicEnabled, chatEnabled, photosEnabled]);
203	
204	  // Refetch the authoritative unread count (used after read/delete events).
205	  const refetchUnread = useCallback(async () => {
206	    try {
207	      const res = await fetch(`/api/v2/notifications?orgId=${orgId}`);
208	      if (res.ok) setUnread((await res.json()).unread ?? 0);
209	    } catch {
210	      /* ignore */
211	    }
212	  }, [orgId]);
213	
214	  // Live bell (mirrors the legacy HeaderBar): INSERT bumps the badge unless the
215	  // drawer is open (then it's read on arrival); UPDATE/DELETE recompute the count.
216	  useEffect(() => {
217	    let cancelled = false;
218	    let sb: Awaited<ReturnType<typeof v2RealtimeClient>> | null = null;
219	    let channel: RealtimeChannel | null = null;
220	    (async () => {
221	      sb = await v2RealtimeClient();
222	      if (cancelled) return;
223	      channel = sb
224	        .channel(`v2-notif-${userId}`)
225	        .on(
226	          "postgres_changes",
227	          { event: "INSERT", schema: "public", table: "v2_notifications", filter: `user_id=eq.${userId}` },
228	          (payload) => {
229	            const n = payload.new as { org_id: string; type: string };
230	            if (n.org_id !== orgId || CHAT_TYPES.includes(n.type)) return;
231	            setOpen((cur) => {
232	              if (cur !== "notifications") setUnread((u) => u + 1);
233	              return cur;
234	            });
235	          },
236	        )
237	        .on(
238	          "postgres_changes",
239	          { event: "UPDATE", schema: "public", table: "v2_notifications", filter: `user_id=eq.${userId}` },
240	          () => refetchUnread(),
241	        )
242	        .on(
243	          "postgres_changes",
244	          { event: "DELETE", schema: "public", table: "v2_notifications", filter: `user_id=eq.${userId}` },
245	          () => refetchUnread(),
246	        )
247	        .subscribe();
248	    })();
249	    return () => {
250	      cancelled = true;
251	      if (sb && channel) sb.removeChannel(channel);
252	    };
253	  }, [userId, orgId, refetchUnread]);
254	
255	  // Keep the OS app-icon badge in sync with the unread count.
256	  useEffect(() => {
257	    syncBadge(unread);
258	  }, [unread]);
259	
260	  // Auto-refresh the push subscription on mount if permission is already granted
261	  // (mirrors the legacy HeaderBar — keeps already-opted-in users subscribed).
262	  useEffect(() => {
263	    if (pushPermission() === "granted") subscribeToV2Push().catch(() => {});
264	  }, []);
265	
266	  // Live chat badge: a new message in any of my rooms (RLS-scoped) bumps/refreshes
267	  // the top-nav chat count even when the drawer is closed.
268	  useEffect(() => {
269	    let cancelled = false;
270	    let sb: Awaited<ReturnType<typeof v2RealtimeClient>> | null = null;
271	    let channel: RealtimeChannel | null = null;
272	    (async () => {
273	      sb = await v2RealtimeClient();
274	      if (cancelled) return;
275	      channel = sb
276	        .channel(`v2-chat-badge-${userId}`)
277	        .on(
278	          "postgres_changes",
279	          { event: "INSERT", schema: "public", table: "v2_chat_messages" },
280	          (payload) => {
281	            const n = payload.new as { sender_id: string };
282	            if (n.sender_id === userId) return;
283	            setOpen((cur) => {
284	              if (cur !== "chat") refetchChatUnread();
285	              return cur;
286	            });
287	          },
288	        )
289	        .subscribe();
290	    })();
291	    return () => {
292	      cancelled = true;
293	      if (sb && channel) sb.removeChannel(channel);
294	    };
295	  }, [userId, refetchChatUnread]);
296	
297	  return (
298	    <>
299	      {/* ── Top bar ─────────────────────────────────────────────────────── */}
300	      <header className={styles.topbar}>
301	        <Link href={`/new/${slug}`} className={styles.topLogo} aria-label={orgName}>
302	          {logoUrl ? (
303	            <img src={logoUrl} alt="" />
304	          ) : (
305	            <span className={styles.topLogoMono}>{orgName.charAt(0).toUpperCase()}</span>
306	          )}
307	        </Link>
308	
