1	import { headers } from "next/headers";
2	import { Playfair_Display, Libre_Franklin } from "next/font/google";
3	import { resolveOrgByHost } from "@/lib/v2/domain";
4	import styles from "./new.module.css";
5	
6	/**
7	 * Inherit the device's font-size preference. iOS Safari only applies the system
8	 * Dynamic Type setting to web pages when the root font is seeded from a system
9	 * text style — `font: -apple-system-body` does exactly that, so every rem-based
10	 * size scales with the user's iOS setting. On Android/desktop the keyword is
11	 * ignored and the browser's own font-size scaling applies. We immediately
12	 * restore our typeface on the body; only the (dynamic) size carries down.
13	 */
14	const OS_FONT_INHERIT_CSS =
15	  "html{font:-apple-system-body;-webkit-text-size-adjust:100%}";
16	
17	const playfair = Playfair_Display({
18	  subsets: ["latin"],
19	  variable: "--font-playfair",
20	  display: "swap",
21	});
22	const libre = Libre_Franklin({
23	  subsets: ["latin"],
24	  variable: "--font-libre",
25	  display: "swap",
26	});
27	
28	export const metadata = {
29	  title: "Golf Platform (preview)",
30	};
31	
32	/**
33	 * The /new theme wrapper — fonts, background, and the per-org brand color (from
34	 * the request host on a custom domain). No visible chrome here: registration/
35	 * admin pages provide their own headers, and the event experience mounts its own
36	 * fixed top-bar/bottom-nav shell.
37	 */
38	export default async function NewLayout({
39	  children,
40	}: {
41	  children: React.ReactNode;
42	}) {
43	  const host = (await headers()).get("host");
44	  const org = await resolveOrgByHost(host);
45	  const brand = org?.primary_color || "#0a5c36";
46	
47	  return (
48	    <div
49	      className={`${playfair.variable} ${libre.variable} ${styles.wrap}`}
50	      style={{ ["--brand" as string]: brand } as React.CSSProperties}
51	    >
52	      <style dangerouslySetInnerHTML={{ __html: OS_FONT_INHERIT_CSS }} />
53	      {children}
54	    </div>
55	  );
56	}
