1	import { NextResponse } from "next/server";
2	import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
3	import { isOrgAdmin } from "@/lib/v2/orgs";
4	
5	/**
6	 * PATCH /api/v2/orgs/[id] — update an org's name, brand color, and/or store link.
7	 * Owner/admin only. Slug is intentionally NOT regenerated on rename (stable URLs).
8	 * Auth: bearer (native) or cookie (web) via v2GetUser.
9	 */
10	export async function PATCH(
11	  request: Request,
12	  { params }: { params: Promise<{ id: string }> }
13	) {
14	  const { id } = await params;
15	  const { userId } = await v2GetUser(request);
16	  if (!userId) {
17	    return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
18	  }
19	
20	  const admin = v2AdminClient();
21	  if (!(await isOrgAdmin(admin, userId, id))) {
22	    return NextResponse.json({ error: "Not allowed" }, { status: 403 });
23	  }
24	
25	  let body: {
26	    name?: string;
27	    primary_color?: string;
28	    name_display?: string;
29	    store_url?: string | null;
30	    store_label?: string | null;
31	    store_enabled?: boolean;
32	    system_name?: string;
33	    member_noun?: string;
34	    member_noun_plural?: string;
35	    onboarding_dismissed?: boolean;
36	  };
37	  try {
38	    body = await request.json();
39	  } catch {
40	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
41	  }
42	
43	  const patch: Record<string, string | null | boolean> = {};
44	  if (typeof body.name === "string") {
45	    const name = body.name.trim();
46	    if (!name) return NextResponse.json({ error: "Name can't be empty" }, { status: 400 });
47	    if (name.length > 80) return NextResponse.json({ error: "Name is too long" }, { status: 400 });
48	    patch.name = name;
49	  }
50	  if (typeof body.primary_color === "string") {
51	    if (!/^#[0-9a-fA-F]{6}$/.test(body.primary_color)) {
52	      return NextResponse.json({ error: "Invalid color" }, { status: 400 });
53	    }
54	    patch.primary_color = body.primary_color;
55	  }
56	  if (body.name_display !== undefined) {
57	    if (body.name_display !== "nickname" && body.name_display !== "real") {
58	      return NextResponse.json({ error: "Invalid name display" }, { status: 400 });
59	    }
60	    patch.name_display = body.name_display;
61	  }
62	  if (body.store_url !== undefined) {
63	    const url = (body.store_url || "").trim();
64	    if (url && !/^https?:\/\/.+/i.test(url)) {
65	      return NextResponse.json({ error: "Store link must start with http(s)://" }, { status: 400 });
66	    }
67	    patch.store_url = url || null;
68	  }
69	  if (body.store_label !== undefined) {
70	    const label = (body.store_label || "").trim();
71	    patch.store_label = label ? label.slice(0, 60) : null;
72	  }
73	  if (typeof body.store_enabled === "boolean") {
74	    patch.store_enabled = body.store_enabled;
75	  }
76	  if (typeof body.system_name === "string") {
77	    const sys = body.system_name.trim();
78	    if (!sys) return NextResponse.json({ error: "System name can't be empty" }, { status: 400 });
79	    if (sys.length > 40) return NextResponse.json({ error: "System name is too long" }, { status: 400 });
80	    patch.system_name = sys;
81	  }
82	  if (typeof body.member_noun === "string") {
83	    const n = body.member_noun.trim();
84	    if (!n) return NextResponse.json({ error: "Member label can't be empty" }, { status: 400 });
85	    if (n.length > 30) return NextResponse.json({ error: "Member label is too long" }, { status: 400 });
86	    patch.member_noun = n;
87	  }
88	  if (typeof body.member_noun_plural === "string") {
89	    const n = body.member_noun_plural.trim();
90	    if (!n) return NextResponse.json({ error: "Member label can't be empty" }, { status: 400 });
91	    if (n.length > 30) return NextResponse.json({ error: "Member label is too long" }, { status: 400 });
92	    patch.member_noun_plural = n;
93	  }
94	  if (typeof body.onboarding_dismissed === "boolean") {
95	    patch.onboarding_dismissed_at = body.onboarding_dismissed ? new Date().toISOString() : null;
96	  }
97	  if (Object.keys(patch).length === 0) {
98	    return NextResponse.json({ error: "Nothing to update" }, { status: 400 });
99	  }
100	  patch.updated_at = new Date().toISOString();
101	
