29	  const startYear = new Date(start + "T00:00:00").getFullYear();
30	  if (end && end !== start) {
31	    const endYear = new Date(end + "T00:00:00").getFullYear();
32	    return endYear !== startYear
33	      ? `${fmt(start)}, ${startYear} – ${fmt(end)}, ${endYear}`
34	      : `${fmt(start)} – ${fmt(end)}, ${startYear}`;
