37	 * host. Only `verified` domains skin the app, so a pending-DNS domain can't
38	 * hijack another org's branding.
39	 */
40	export async function resolveOrgByHost(
41	  host: string | null | undefined
42	): Promise<OrgBranding | null> {
43	  if (isDefaultHost(host)) return null;
44	  const admin = v2AdminClient();
